import{_ as o,a0 as i,w as p,s as g,ao as r,I as t,x as n,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用 syslog-ng 從遠程 Linux 機器上收集日誌 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 syslog-ng 從遠程 Linux 機器上收集日誌 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 syslog-ng 從遠程 Linux 機器上收集日誌 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 syslog-ng 從遠程 Linux 機器上收集日誌 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180109 How to use syslog-ng to collect logs from remote Linux machines","title":"如何使用 syslog-ng 從遠程 Linux 機器上收集日誌","tag":"201803","desc":""},"relativePath":"201803/20180109 How to use syslog-ng to collect logs from remote Linux machines.md","filePath":"[post].md"}'),c={name:"201803/20180109 How to use syslog-ng to collect logs from remote Linux machines.md"};function d(u,s,h,y,m,b){const a=i("Link");return p(),g("div",null,[s[13]||(s[13]=r(`<h1 id="如何使用-syslog-ng-從遠程-linux-機器上收集日誌" tabindex="-1">如何使用 syslog-ng 從遠程 Linux 機器上收集日誌 <a class="header-anchor" href="#如何使用-syslog-ng-從遠程-linux-機器上收集日誌" aria-label="Permalink to “如何使用 syslog-ng 從遠程 Linux 機器上收集日誌”">​</a></h1><p>![linuxhero.jpg][1]</p><p>如果你的數據中心全是 Linux 服務器，而你就是系統管理員。那麼你的其中一項工作內容就是查看服務器的日誌文件。但是，如果你在大量的機器上去查看日誌文件，那麼意味着你需要挨個去登入到機器中來閲讀日誌文件。如果你管理的機器很多，僅這項工作就可以花費你一天的時間。</p><p>另外的選擇是，你可以配置一台單獨的 Linux 機器去收集這些日誌。這將使你的每日工作更加高效。要實現這個目的，有很多的不同系統可供你選擇，而 syslog-ng 就是其中之一。</p><p>syslog-ng 的不足是文檔並不容易梳理。但是，我已經解決了這個問題，我可以通過這種方法馬上進行安裝和配置 syslog-ng。下面我將在 Ubuntu Server 16.04 上示範這兩種方法：</p><ul><li>UBUNTUSERVERVM 的 IP 地址是 192.168.1.118 ，將配置為日誌收集器</li><li>UBUNTUSERVERVM2 將配置為一個客户端，發送日誌文件到收集器</li></ul><p>現在我們來開始安裝和配置。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>安裝很簡單。為了儘可能容易，我將從標準倉庫安裝。打開一個終端窗口，運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install syslog-ng</span></span></code></pre></div><p>你必須在收集器和客户端的機器上都要運行上面的命令。安裝完成之後，你將開始配置。</p><h3 id="配置收集器" tabindex="-1">配置收集器 <a class="header-anchor" href="#配置收集器" aria-label="Permalink to “配置收集器”">​</a></h3><p>現在，我們開始日誌收集器的配置。它的配置文件是 <code>/etc/syslog-ng/syslog-ng.conf</code>。syslog-ng 安裝完成時就已經包含了一個配置文件。我們不使用這個默認的配置文件，可以使用 <code>mv /etc/syslog-ng/syslog-ng.conf /etc/syslog-ng/syslog-ng.conf.BAK</code> 將這個自帶的默認配置文件重命名。現在使用 <code>sudo nano /etc/syslog/syslog-ng.conf</code> 命令創建一個新的配置文件。在這個文件中添加如下的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@version: 3.5</span></span>
<span class="line"><span>@include &quot;scl.conf&quot;</span></span>
<span class="line"><span>@include &quot;\`scl-root\`/system/tty10.conf&quot;</span></span>
<span class="line"><span>    options {</span></span>
<span class="line"><span>        time-reap(30);</span></span>
<span class="line"><span>        mark-freq(10);</span></span>
<span class="line"><span>        keep-hostname(yes);</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span>    source s_local { system(); internal(); };</span></span>
<span class="line"><span>    source s_network {</span></span>
<span class="line"><span>        syslog(transport(tcp) port(514));</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span>    destination d_local {</span></span>
<span class="line"><span>    file(&quot;/var/log/syslog-ng/messages_\${HOST}&quot;); };</span></span>
<span class="line"><span>    destination d_logs {</span></span>
<span class="line"><span>        file(</span></span>
<span class="line"><span>            &quot;/var/log/syslog-ng/logs.txt&quot;</span></span>
<span class="line"><span>            owner(&quot;root&quot;)</span></span>
<span class="line"><span>            group(&quot;root&quot;)</span></span>
<span class="line"><span>            perm(0777)</span></span>
<span class="line"><span>            ); };</span></span>
<span class="line"><span>    log { source(s_local); source(s_network); destination(d_logs); };</span></span></code></pre></div><p>需要注意的是，syslog-ng 使用 514 端口，你需要確保在你的網絡上它可以被訪問。</p><p>保存並關閉這個文件。上面的配置將轉存期望的日誌文件（由 <code>system()</code> 和 <code>internal()</code> 指出）到 <code>/var/log/syslog-ng/logs.txt</code> 中。因此，你需要使用如下的命令去創建所需的目錄和文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /var/log/syslog-ng</span></span>
<span class="line"><span>sudo touch /var/log/syslog-ng/logs.txt</span></span></code></pre></div><p>使用如下的命令啓動和啓用 syslog-ng：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start syslog-ng</span></span>
<span class="line"><span>sudo systemctl enable syslog-ng</span></span></code></pre></div><h3 id="配置客户端" tabindex="-1">配置客户端 <a class="header-anchor" href="#配置客户端" aria-label="Permalink to “配置客户端”">​</a></h3><p>我們將在客户端上做同樣的事情（移動默認配置文件並創建新配置文件）。拷貝下列文本到新的客户端配置文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@version: 3.5</span></span>
<span class="line"><span>@include &quot;scl.conf&quot;</span></span>
<span class="line"><span>@include &quot;\`scl-root\`/system/tty10.conf&quot;</span></span>
<span class="line"><span>source s_local { system(); internal(); };</span></span>
<span class="line"><span>destination d_syslog_tcp {</span></span>
<span class="line"><span>              syslog(&quot;192.168.1.118&quot; transport(&quot;tcp&quot;) port(514)); };</span></span>
<span class="line"><span>log { source(s_local);destination(d_syslog_tcp); };</span></span></code></pre></div><p>請注意：請將 IP 地址修改為收集器的 IP 地址。</p><p>保存和關閉這個文件。與在配置為收集器的機器上一樣的方法啓動和啓用 syslog-ng。</p><h2 id="查看日誌文件" tabindex="-1">查看日誌文件 <a class="header-anchor" href="#查看日誌文件" aria-label="Permalink to “查看日誌文件”">​</a></h2><p>回到你的配置為收集器的服務器上，運行這個命令 <code>sudo tail -f /var/log/syslog-ng/logs.txt</code>。你將看到包含了收集器和客户端的日誌條目的輸出（圖 A）。</p><p><img src="https://tr4.cbsistatic.com/hub/i/2018/01/09/6a24e5c0-6a29-46d3-8a66-bc72747b5beb/6f94d3e6c6c2121fab6223ed9d8c6aa6/syslognga.jpg" alt="圖 A"></p><p>恭喜你！syslog-ng 已經正常工作了。你現在可以登入到你的收集器上查看本地機器和遠程客户端的日誌了。如果你的數據中心有很多 Linux 服務器，在每台服務器上都安裝上 syslog-ng 並配置它們作為客户端發送日誌到收集器，這樣你就不需要登入到每個機器去查看它們的日誌了。</p><hr>`,29)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.techrepublic.com/article/how-to-use-syslog-ng-to-collect-logs-from-remote-linux-machines/"},{default:l(()=>[...s[0]||(s[0]=[n("https://www.techrepublic.com/article/how-to-use-syslog-ng-to-collect-logs-from-remote-linux-machines/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=n("作者：",-1)),e(a,{href:"%5B1%5D:https://tr1.cbsistatic.com/hub/i/r/2017/01/11/51204409-68e0-49b8-a637-01af26be85f6/resize/770x/688dfedad4ed30ec4baf548c2adb8cd4/linuxhero.jpg"},{default:l(()=>[...s[2]||(s[2]=[n("Jack Wallen",-1)])]),_:1}),s[6]||(s[6]=n(" 譯者：",-1)),e(a,{href:"https://github.com/qhwdw"},{default:l(()=>[...s[3]||(s[3]=[n("qhwdw",-1)])]),_:1}),s[7]||(s[7]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[8]||(s[8]=[n("LCTT",-1)])]),_:1}),s[11]||(s[11]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...s[9]||(s[9]=[n("Linux中國",-1)])]),_:1}),s[12]||(s[12]=n(" 榮譽推出",-1))])])}const _=o(c,[["render",d]]);export{x as __pageData,_ as default};
